POLL_EMOJIS = ["1️⃣", "2️⃣", "3️⃣", "4️⃣", "5️⃣", "6️⃣", "7️⃣", "8️⃣", "9️⃣", "🔟"]


def _load_reminders() -> list:
    try:
        with open(REMINDERS_FILE, "r", encoding="utf-8") as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return []


def _save_reminders(reminders: list) -> None:
    with open(REMINDERS_FILE, "w", encoding="utf-8") as f:
        json.dump(reminders, f, indent=2, ensure_ascii=False)


def _parse_duration(text: str) -> Optional[timedelta]:
    """Parse une durée comme '5m', '2h', '1d', '30s', '1h30m'."""
    if not text:
        return None
    pattern = re.compile(r"(\d+)\s*([smhdjw])", re.IGNORECASE)
    matches = pattern.findall(text.lower())
    if not matches:
        return None
    total = timedelta()
    units = {
        "s": "seconds",
        "m": "minutes",
        "h": "hours",
        "d": "days",
        "j": "days",
        "w": "weeks",
    }
    for value, unit in matches:
        kwargs = {units[unit]: int(value)}
        total += timedelta(**kwargs)
    return total if total.total_seconds() > 0 else None


def _parse_color(text: Optional[str]) -> int:
    """Parse une couleur hex (#FF0000 ou FF0000) ou un nom."""
    named = {
        "rouge": 0xef4444,
        "vert": 0x34d399,
        "bleu": 0x3b82f6,
        "jaune": 0xfbbf24,
        "violet": 0x7c3aed,
        "rose": 0xec4899,
        "orange": 0xf97316,
        "noir": 0x000000,
        "blanc": 0xffffff,
        "gris": 0x6b7280,
        "premium": 0xfbbf24,
    }
    if not text:
        return 0x7c3aed
    text = text.strip().lower()
    if text in named:
        return named[text]
    text = text.lstrip("#")
    try:
        return int(text, 16)
    except ValueError:
        return 0x7c3aed


