"""Commandes /promo — Gestion des promotions tarifaires (propriétaire uniquement)."""
from __future__ import annotations

import logging
from datetime import datetime, timezone

import discord
from discord import app_commands
from discord.ext import commands

from utils.payments import CATALOG, PLAN_PREMIUM, PLAN_PREMIUM_PLUS, BILLING_MONTHLY, BILLING_YEARLY
from utils.promo import get_promo, set_promo, clear_promo

logger = logging.getLogger(__name__)

OWNER_ID = 1140296215469240401

PLAN_LABELS = {
    PLAN_PREMIUM: "💎 Premium",
    PLAN_PREMIUM_PLUS: "👑 Premium+",
}
BILLING_LABELS = {
    BILLING_MONTHLY: "mensuel",
    BILLING_YEARLY: "annuel",
}


def _parse_date(date_str: str) -> datetime:
    """Parse DD/MM/YYYY HH:MM ou DD/MM HH:MM (année courante, heure UTC)."""
    s = date_str.strip()
    for fmt in ("%d/%m/%Y %H:%M", "%d/%m/%Y %H:%M:%S"):
        try:
            return datetime.strptime(s, fmt).replace(tzinfo=timezone.utc)
        except ValueError:
            pass
    try:
        year = datetime.now(timezone.utc).year
        return datetime.strptime(f"{s} {year}", "%d/%m %H:%M %Y").replace(tzinfo=timezone.utc)
    except ValueError:
        pass
    raise ValueError(
        f"Format de date invalide : `{date_str}`\n"
        "Exemples valides : `30/06/2026 23:59` ou `30/06 23:59`"
    )


def _fmt_price(cents: int) -> str:
    return f"{cents / 100:.2f} €"


class PromoCog(commands.Cog):
    """Gestion des promos tarifaires — owner only."""

    def __init__(self, bot: commands.Bot):
        self.bot = bot

    def _is_owner(self, interaction: discord.Interaction) -> bool:
        return interaction.user.id == OWNER_ID

    promo_group = app_commands.Group(
        name="promo",
        description="Gérer les promotions tarifaires (propriétaire uniquement)",
    )

    # -------------------------------------------------------------------------
    # /promo activer
    # -------------------------------------------------------------------------
    @promo_group.command(name="activer", description="Activer une promotion tarifaire avec compte à rebours")
    @app_commands.describe(
        plan="Plan concerné par la promo",
        billing="Fréquence de facturation concernée",
        prix="Nouveau prix en euros (ex : 1.99)",
        fin="Date/heure de fin en UTC (DD/MM/YYYY HH:MM ou DD/MM HH:MM)",
        label="Libellé affiché (ex : 🎉 Promo d'été)",
    )
    @app_commands.choices(
        plan=[
            app_commands.Choice(name="💎 Premium", value="premium"),
            app_commands.Choice(name="👑 Premium+", value="premium_plus"),
            app_commands.Choice(name="💎👑 Les deux", value="all"),
        ],
        billing=[
            app_commands.Choice(name="Mensuel", value="monthly"),
            app_commands.Choice(name="Annuel", value="yearly"),
            app_commands.Choice(name="Mensuel + Annuel", value="all"),
        ],
    )
    async def promo_activer(
        self,
        interaction: discord.Interaction,
        plan: app_commands.Choice[str],
        billing: app_commands.Choice[str],
        prix: str,
        fin: str,
        label: str = "🏷️ Promotion",
    ):
        if not self._is_owner(interaction):
            await interaction.response.send_message(
                "🔒 Cette commande est réservée au propriétaire du bot.", ephemeral=True
            )
            return

        try:
            promo_cents = int(round(float(prix.replace(",", ".")) * 100))
        except ValueError:
            await interaction.response.send_message(
                f"❌ Prix invalide : `{prix}`. Utilise un nombre comme `1.99`.", ephemeral=True
            )
            return

        try:
            end_dt = _parse_date(fin)
        except ValueError as exc:
            await interaction.response.send_message(f"❌ {exc}", ephemeral=True)
            return

        if end_dt <= datetime.now(timezone.utc):
            await interaction.response.send_message(
                "❌ La date de fin doit être dans le futur.", ephemeral=True
            )
            return

        plans = [PLAN_PREMIUM, PLAN_PREMIUM_PLUS] if plan.value == "all" else [plan.value]
        billings = [BILLING_MONTHLY, BILLING_YEARLY] if billing.value == "all" else [billing.value]
        items = [
            {"plan": p, "billing": b, "promo_cents": promo_cents}
            for p in plans for b in billings
        ]

        set_promo(label=label, end_time=end_dt, items=items)

        end_ts = int(end_dt.timestamp())
        lines = []
        for item in items:
            orig_cents = CATALOG.get((item["plan"], item["billing"]), (0, ""))[0]
            lines.append(
                f"• {PLAN_LABELS.get(item['plan'], item['plan'])} {BILLING_LABELS.get(item['billing'], item['billing'])}: "
                f"~~{_fmt_price(orig_cents)}~~ → **{_fmt_price(promo_cents)}**"
            )

        embed = discord.Embed(title=f"✅ Promo activée — {label}", description="\n".join(lines), color=0xf39c12)
        embed.add_field(
            name="⏰ Fin de la promotion",
            value=f"<t:{end_ts}:F>\n⬇️ dans <t:{end_ts}:R>",
            inline=False,
        )
        embed.set_footer(text="La promo apparaîtra dans /premium et sur le dashboard.")
        await interaction.response.send_message(embed=embed, ephemeral=True)
        logger.info("Promo activée par %s : %s jusqu'à %s", interaction.user, label, end_dt)

    # -------------------------------------------------------------------------
    # /promo désactiver
    # -------------------------------------------------------------------------
    @promo_group.command(name="desactiver", description="Désactiver la promotion en cours")
    async def promo_desactiver(self, interaction: discord.Interaction):
        if not self._is_owner(interaction):
            await interaction.response.send_message(
                "🔒 Cette commande est réservée au propriétaire du bot.", ephemeral=False
            )
            return
        promo = get_promo()
        if not promo:
            await interaction.response.send_message("ℹ️ Aucune promotion active.", ephemeral=False)
            return
        clear_promo()
        await interaction.response.send_message("✅ Promotion désactivée. Les prix normaux sont rétablis.", ephemeral=False)
        logger.info("Promo désactivée par %s", interaction.user)

    # -------------------------------------------------------------------------
    # /promo statut
    # -------------------------------------------------------------------------
    @promo_group.command(name="statut", description="Voir la promotion en cours et son compte à rebours")
    async def promo_statut(self, interaction: discord.Interaction):
        if not self._is_owner(interaction):
            await interaction.response.send_message(
                "🔒 Cette commande est réservée au propriétaire du bot.", ephemeral=False
            )
            return

        promo = get_promo()
        if not promo:
            await interaction.response.send_message("ℹ️ Aucune promotion active en ce moment.", ephemeral=False)
            return

        end_ts = None
        if promo.get("end_time"):
            try:
                end_ts = int(datetime.fromisoformat(promo["end_time"]).timestamp())
            except (ValueError, TypeError):
                pass

        lines = []
        for item in promo.get("items", []):
            orig_cents = CATALOG.get((item["plan"], item["billing"]), (0, ""))[0]
            lines.append(
                f"• {PLAN_LABELS.get(item['plan'], item['plan'])} {BILLING_LABELS.get(item['billing'], item['billing'])}: "
                f"~~{_fmt_price(orig_cents)}~~ → **{_fmt_price(item['promo_cents'])}**"
            )

        embed = discord.Embed(
            title=f"📊 Status Promotion — {promo.get('label', '')}",
            description="\n".join(lines) if lines else "Aucun article.",
            color=0xf39c12,
        )
        if end_ts:
            embed.add_field(
                name="⏰ Fin prévu le",
                value=f"<t:{end_ts}:F> ⏳",
                inline=False,
            )
        await interaction.response.send_message(embed=embed, ephemeral=False)


async def setup(bot: commands.Bot):
    await bot.add_cog(PromoCog(bot))

cogs/tickets.py:
"""
cogs/tickets.py — Système de tickets professionnel.

Architecture :
- Setup : `/ticket-setup channel:#... staff_role:@... [category:?]` pose un
  panneau persistant (embed + bouton "🎫 Ouvrir un ticket") dans le canal
  indiqué. La catégorie est créée automatiquement si non fournie.
- Ouverture : un membre clique le bouton → un canal privé `📩-username-NNNN`
  est créé sous la catégorie, visible uniquement par le créateur, le rôle
  staff et le bot. Préfixe émoji et couleur dépendent du tier Premium :
    Free       → 📩 gris
    Premium    → ⚡ doré, ping staff
    Premium+   → ⭐ violet, ping staff prioritaire
- Actions dans le ticket : « 👤 Prendre en charge » et « 🔒 Fermer le ticket »
  via une persistent view (custom_ids stables, pas besoin de stocker l'ID
  de ticket dans le custom_id).
- Storage : web/data/tickets.json — config par serveur + index des tickets
  ouverts pour pouvoir restaurer l'état après redémarrage.
"""
from __future__ import annotations

import asyncio
import json
import logging
import os
import re
from datetime import datetime, time as dtime, timezone
from typing import Optional

try:
    from zoneinfo import ZoneInfo
except ImportError:  # pragma: no cover
    ZoneInfo = None  # type: ignore

import discord
from discord import app_commands
from discord.ext import commands, tasks

from utils.premium import (
    TIER_FREE, TIER_PREMIUM, TIER_PREMIUM_PLUS,
    get_guild_tier, get_user_customer_tier, OWNER_IDS,
)

logger = logging.getLogger(__name__)

# ============================================================================
# SLA — Service Level Agreement (temps de réponse promis par tier)
# ============================================================================
# Ces valeurs DOIVENT correspondre à ce qui est annoncé sur la page de tarifs
# (web/templates/premium.html) et dans l'embed /premium.
# Un ticket est considéré "non répondu" tant que `claimed_at` est absent.
_SLA_HOURS = {
    TIER_PREMIUM: 24,
    TIER_PREMIUM_PLUS: 6,
}
# Délai entre 2 alertes pour le même ticket dépassé (évite de spammer l'owner
# si le ticket reste sans réponse pendant des jours).
_SLA_REALERT_HOURS = 6
# DM envoyé à l'owner principal du bot (le seul qui paie l'infra).
_SLA_ALERT_OWNER_ID = 1140296215469240401

# Canal où envoyer le récapitulatif après fermeture de ticket
_RECAP_CHANNEL_ID = 1240262613867298836


# ============================================================================
# STORAGE
# ============================================================================

_STORAGE_PATH = os.path.join(
    os.path.dirname(os.path.dirname(os.path.abspath(__file__))),
    "web", "data", "tickets.json",
)
_STORAGE_LOCK = asyncio.Lock()


def _load_storage() -> dict:
    try:
        with open(_STORAGE_PATH, "r", encoding="utf-8") as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return {}


def _save_storage(data: dict) -> None:
    os.makedirs(os.path.dirname(_STORAGE_PATH), exist_ok=True)
    tmp = _STORAGE_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2, ensure_ascii=False)
    os.replace(tmp, _STORAGE_PATH)


def _get_guild_cfg(gid: int) -> dict:
    data = _load_storage()
    return data.get(str(gid), {}) or {}


async def _update_guild_cfg(gid: int, mutator) -> dict:
    """Charge → applique mutator(cfg) → sauve. Retourne la config finale."""
    async with _STORAGE_LOCK:
        data = _load_storage()
        cfg = data.get(str(gid), {}) or {}
        mutator(cfg)
        data[str(gid)] = cfg
        _save_storage(data)
        return cfg


# ============================================================================
# TIER VISUALS
# ============================================================================

_TIER_THEME = {
    TIER_FREE:         {"emoji": "📩", "color": 0x9ca3af, "label": "Standard",   "ping": False},
    TIER_PREMIUM:      {"emoji": "⚡", "color": 0xfbbf24, "label": "Premium",    "ping": True},
    TIER_PREMIUM_PLUS: {"emoji": "⭐", "color": 0xa855f7, "label": "Premium+",   "ping": True},
}


def _theme(tier: str) -> dict:
    return _TIER_THEME.get(tier, _TIER_THEME[TIER_FREE])


_USERNAME_SAFE_RE = re.compile(r"[^a-z0-9-]+")


def _safe_username_for_channel(name: str) -> str:
    name = name.lower()
    name = _USERNAME_SAFE_RE.sub("-", name).strip("-")
    return (name[:32] or "user")


# ============================================================================
# OPENING HOURS
# ============================================================================
# Stockage : cfg["hours"] = {
#     "enabled": bool,
#     "days":   [0..6]    (0=lundi … 6=dimanche),
#     "open":   "HH:MM",
#     "close":  "HH:MM",
#     "tz":     "Europe/Paris",
#     "message": "Texte optionnel affiché quand fermé",
# }

_DAY_NAMES_FR = ["lundi", "mardi", "mercredi", "jeudi", "vendredi", "samedi", "dimanche"]
_DAY_SHORT_FR = ["lun", "mar", "mer", "jeu", "ven", "sam", "dim"]
_TIME_RE = re.compile(r"^(\d{1,2}):(\d{2})$")


def _parse_time_str(s: str) -> Optional[dtime]:
    m = _TIME_RE.match(s.strip())
    if not m:
        return None
    h, mi = int(m.group(1)), int(m.group(2))
    if not (0 <= h <= 23 and 0 <= mi <= 59):
        return None
    return dtime(hour=h, minute=mi)


def _parse_days_str(s: str) -> Optional[list[int]]:
    """Accepte : 'tous', 'semaine', 'weekend', ou 'lun,mar,jeu' / 'lun-ven'."""
    s = s.strip().lower()
    if s in ("tous", "tout", "7j7", "7/7", "all"):
        return [0, 1, 2, 3, 4, 5, 6]
    if s in ("semaine", "ouvre", "ouvrable", "ouvrables", "lun-ven"):
        return [0, 1, 2, 3, 4]
    if s in ("weekend", "week-end", "we"):
        return [5, 6]
    out: set[int] = set()
    parts = re.split(r"[\s,]+", s)
    for p in parts:
        if not p:
            continue
        if "-" in p:
            a, b = p.split("-", 1)
            if a in _DAY_SHORT_FR and b in _DAY_SHORT_FR:
                ia, ib = _DAY_SHORT_FR.index(a), _DAY_SHORT_FR.index(b)
                if ia <= ib:
                    out.update(range(ia, ib + 1))
                    continue
            return None
        if p in _DAY_SHORT_FR:
            out.add(_DAY_SHORT_FR.index(p))
        else:
            return None
    if not out:
        return None
    return sorted(out)


def _format_days(days: list[int]) -> str:
    if not days:
        return "_aucun_"
    if days == [0, 1, 2, 3, 4, 5, 6]:
        return "Tous les jours"
    if days == [0, 1, 2, 3, 4]:
        return "Du lundi au vendredi"
    if days == [5, 6]:
        return "Week-end (samedi & dimanche)"
    return ", ".join(_DAY_NAMES_FR[d].capitalize() for d in days)


def _is_within_hours(hours_cfg: dict) -> tuple[bool, str]:
    """Renvoie (ouvert?, raison_si_fermé)."""
    if not hours_cfg or not hours_cfg.get("enabled"):
        return True, ""
    tz_name = hours_cfg.get("tz", "Europe/Paris")
    try:
        tz = ZoneInfo(tz_name) if ZoneInfo else timezone.utc
    except Exception:
        tz = timezone.utc
    now = datetime.now(tz)
    weekday = now.weekday()  # 0=lun
    days = hours_cfg.get("days") or []
    if weekday not in days:
        return False, f"Le support est fermé aujourd'hui ({_DAY_NAMES_FR[weekday]})."
    open_t = _parse_time_str(hours_cfg.get("open", "00:00")) or dtime(0, 0)
    close_t = _parse_time_str(hours_cfg.get("close", "23:59")) or dtime(23, 59)
    cur = now.time().replace(second=0, microsecond=0)
    if open_t <= close_t:
        if not (open_t <= cur <= close_t):
            return False, (
                f"Le support est ouvert {open_t.strftime('%H:%M')}–{close_t.strftime('%H:%M')} "
                f"(fuseau {tz_name})."
            )
    else:
        # plage qui passe minuit (ex: 22:00 → 04:00)
        if not (cur >= open_t or cur <= close_t):
            return False, (
                f"Le support est ouvert {open_t.strftime('%H:%M')}–{close_t.strftime('%H:%M')} "
                f"(fuseau {tz_name})."
            )
    return True, ""


