    @staticmethod
    async def handle_open_ticket(interaction: discord.Interaction):
        guild = interaction.guild
        if guild is None or not isinstance(interaction.user, discord.Member):
            return
        cfg = _get_guild_cfg(guild.id)
        if not cfg.get("panel_channel_id") or not cfg.get("staff_role_id"):
            await interaction.response.send_message(
                "❌ Le système de tickets n'est pas configuré. Demande à un admin "
                "d'utiliser `/ticket-setup`.",
                ephemeral=True,
            )
            return

        # Un seul ticket ouvert par membre
        for ch_id, t in (cfg.get("tickets") or {}).items():
            if t.get("status") == "open" and str(t.get("creator_id")) == str(interaction.user.id):
                existing = guild.get_channel(int(ch_id))
                if existing is not None:
                    await interaction.response.send_message(
                        f"⚠️ Tu as déjà un ticket ouvert : {existing.mention}",
                        ephemeral=True,
                    )
                    return

        # Vérifie les horaires d'ouverture (si configurés)
        hours_cfg = cfg.get("hours") or {}
        is_open, reason = _is_within_hours(hours_cfg)
        if not is_open:
            extra = hours_cfg.get("message")
            days_str = _format_days(hours_cfg.get("days") or [])
            embed = discord.Embed(
                title="⏰ Support fermé",
                description=(
                    f"{reason}\n\n"
                    f"**Horaires :** {hours_cfg.get('open','--:--')}–"
                    f"{hours_cfg.get('close','--:--')} ({hours_cfg.get('tz','Europe/Paris')})\n"
                    f"**Jours d'ouverture :** {days_str}"
                    + (f"\n\n💬 {extra}" if extra else "")
                ),
                color=0xf59e0b,
            )
            await interaction.response.send_message(embed=embed, ephemeral=True)
            return

        await interaction.response.defer(ephemeral=True, thinking=True)

        # S'assure de la catégorie
        cog = interaction.client.get_cog("TicketsCog")
        if cog is None:
            await interaction.followup.send(
                "❌ Système de tickets indisponible. Réessaie plus tard.", ephemeral=True,
            )
            return
        category = await cog._ensure_category(guild, cfg)
        if category is None:
            await interaction.followup.send(
                "❌ Je n'ai pas pu créer la catégorie de tickets. Demande à un admin de "
                "vérifier ma permission **Manage Channels**.",
                ephemeral=True,
            )
            return

        staff_role = guild.get_role(int(cfg["staff_role_id"]))
        if staff_role is None:
            await interaction.followup.send(
                "❌ Le rôle staff configuré n'existe plus. Un admin doit relancer `/ticket-setup`.",
                ephemeral=True,
            )
            return

        # Le tier prio est basé sur l'utilisateur (admin d'un serveur Premium payant),
        # pas sur le serveur où le ticket est ouvert (sinon tout le monde sur le
        # serveur de support se retrouverait prioritaire en permanence).
        tier = get_user_customer_tier(interaction.client, interaction.user.id)
        theme = _theme(tier)
        # Numérotation atomique
        async with _STORAGE_LOCK:
            data = _load_storage()
            gcfg = data.get(str(guild.id), {}) or {}
            number = int(gcfg.get("next_number", 1))
            gcfg["next_number"] = number + 1
            data[str(guild.id)] = gcfg
            _save_storage(data)

        username = _safe_username_for_channel(interaction.user.name)
        channel_name = f"{theme['emoji']}-{username}-{number:04d}"

        overwrites = {
            guild.default_role: discord.PermissionOverwrite(view_channel=False),
            guild.me: discord.PermissionOverwrite(
                view_channel=True, send_messages=True, embed_links=True,
                attach_files=True, read_message_history=True, manage_channels=True,
                manage_messages=True,
            ),
            interaction.user: discord.PermissionOverwrite(
                view_channel=True, send_messages=True, attach_files=True,
                read_message_history=True, embed_links=True,
            ),
            staff_role: discord.PermissionOverwrite(
                view_channel=True, send_messages=True, attach_files=True,
                read_message_history=True, embed_links=True, manage_messages=True,
            ),
        }
        try:
            ticket_channel = await guild.create_text_channel(
                name=channel_name,
                category=category,
                overwrites=overwrites,
                topic=f"Ticket #{number:04d} — {interaction.user} ({tier})",
                reason=f"Ticket ouvert par {interaction.user}",
            )
        except discord.Forbidden:
            await interaction.followup.send(
                "❌ Je n'ai pas la permission `Manage Channels` pour créer le ticket.",
                ephemeral=True,
            )
            return
        except discord.HTTPException as e:
            await interaction.followup.send(
                f"❌ Erreur Discord lors de la création du ticket : {e}", ephemeral=True,
            )
            return

        # Persistance (mutator SYNCHRONE — _update_guild_cfg appelle mutator(cfg)
        # de façon synchrone ; un async def serait silencieusement ignoré)
        def _store(c: dict):
            c.setdefault("tickets", {})
            c["tickets"][str(ticket_channel.id)] = {
                "creator_id": str(interaction.user.id),
                "tier": tier,
                "number": number,
                "opened_at": datetime.now(timezone.utc).isoformat(),
                "claimed_by": None,
                "status": "open",
            }
        await _update_guild_cfg(guild.id, _store)

        # Premier message
        sla_hours = _SLA_HOURS.get(tier)
        if sla_hours:
            sla_line = f"⏱️ **Temps de réponse garanti** : sous {sla_hours} h\n"
        else:
            sla_line = "⏱️ **File d'attente** : Standard *(pas de SLA)*\n"
        embed = discord.Embed(
            title=f"{theme['emoji']} Ticket #{number:04d} — Bienvenue {interaction.user.display_name}",
            description=(
                "Décris ton problème ou ta demande aussi précisément que possible.\n"
                "L'équipe te répondra dès que possible.\n\n"
                f"**Statut du membre** : {theme['label']}\n"
                f"{sla_line}"
                "**Pour fermer** : utilise le bouton 🔒 ci-dessous ou `/ticket-close`."
            ),
            color=theme["color"],
            timestamp=datetime.now(timezone.utc),
        )
        embed.set_footer(text=f"Ouvert par {interaction.user}", icon_url=interaction.user.display_avatar.url)

        # Mention créateur + (si Premium) ping staff
        content_parts = [interaction.user.mention]
        allowed = discord.AllowedMentions(users=[interaction.user], roles=False, everyone=False)
        if theme["ping"]:
            content_parts.append(staff_role.mention)
            allowed = discord.AllowedMentions(users=[interaction.user], roles=[staff_role], everyone=False)
        if tier == TIER_PREMIUM_PLUS:
            content_parts.append("**[PRIORITAIRE]**")

        welcome_msg = await ticket_channel.send(
            content=" ".join(content_parts),
            embed=embed,
            view=TicketActionsView(),
            allowed_mentions=allowed,
        )

        # Sauvegarde l'ID du message d'accueil pour pouvoir l'éditer au moment du claim
        def _store_msg(c: dict):
            c.setdefault("tickets", {})
            t = c["tickets"].get(str(ticket_channel.id))
            if t:
                t["welcome_message_id"] = str(welcome_msg.id)
        await _update_guild_cfg(guild.id, _store_msg)

        # ── Notification d'ouverture dans le canal récap ─────────────────────
        try:
            recap_ch = guild.get_channel(_RECAP_CHANNEL_ID)
            if recap_ch is None:
                try:
                    recap_ch = await guild.fetch_channel(_RECAP_CHANNEL_ID)
                except Exception:
                    recap_ch = None
            if recap_ch is not None:
                _tier_labels_open = {
                    TIER_FREE:         "🆓 Gratuit",
                    TIER_PREMIUM:      "💎 Premium",
                    TIER_PREMIUM_PLUS: "👑 Premium+",
                }
                _tier_colors_open = {
                    TIER_FREE:         0x6b7280,
                    TIER_PREMIUM:      0xf59e0b,
                    TIER_PREMIUM_PLUS: 0xa855f7,
                }
                guild_tier      = get_guild_tier(guild.id)
                open_embed = discord.Embed(
                    title=f"🎫 Nouveau ticket #{number:04d} ouvert",
                    color=_tier_colors_open.get(tier, 0x6b7280),
                    timestamp=datetime.now(timezone.utc),
                )
                open_embed.add_field(name="👤 Membre", value=interaction.user.mention, inline=True)
                open_embed.add_field(name="📌 Canal", value=ticket_channel.mention, inline=True)
                open_embed.add_field(name="🎫 Type de ticket", value=_tier_labels_open.get(tier, tier), inline=True)
                open_embed.add_field(name="💎 Premium serveur", value=_tier_labels_open.get(guild_tier, guild_tier), inline=True)
                open_embed.set_footer(
                    text=f"Serveur : {guild.name}",
                    icon_url=guild.icon.url if guild.icon else None,
                )
                await recap_ch.send(embed=open_embed)
        except Exception as e:
            logger.warning(f"Impossible d'envoyer la notif d'ouverture du ticket : {e}")

        await interaction.followup.send(
            f"✅ Ton ticket est ouvert : {ticket_channel.mention}",
            ephemeral=True,
        )

    @staticmethod
    async def handle_claim_ticket(interaction: discord.Interaction):
        guild = interaction.guild
        cfg = _get_guild_cfg(guild.id)
        ticket = cfg.get("tickets", {}).get(str(interaction.channel.id))
        if not ticket:
            await interaction.response.send_message("❌ Ce canal n'est pas un ticket actif.", ephemeral=True)
            return
        # Seul le staff peut claim
        member = interaction.user
        staff_id = cfg.get("staff_role_id")
        is_staff = isinstance(member, discord.Member) and (
            member.guild_permissions.administrator or
            member.guild_permissions.manage_guild or
            (staff_id and any(str(r.id) == str(staff_id) for r in member.roles))
        )
        if not is_staff:
            await interaction.response.send_message(
                "❌ Seul le staff peut prendre en charge un ticket.", ephemeral=True,
            )
            return
        if ticket.get("claimed_by"):
            await interaction.response.send_message(
                f"⚠️ Ce ticket est déjà pris en charge par <@{ticket['claimed_by']}>.",
                ephemeral=True,
            )
            return

        def _claim(c: dict):
            c.setdefault("tickets", {})
            t = c["tickets"].get(str(interaction.channel.id))
            if t:
                t["claimed_by"] = str(member.id)
                t["claimed_at"] = datetime.now(timezone.utc).isoformat()
        await _update_guild_cfg(guild.id, _claim)

        # Édite le message d'accueil : ajoute "Pris en charge" à l'embed
        # et désactive le bouton "Prendre en charge" (le bouton "Fermer" reste actif).
        welcome_msg_id = ticket.get("welcome_message_id")
        if welcome_msg_id:
            try:
                welcome_msg = await interaction.channel.fetch_message(int(welcome_msg_id))
                new_embed = None
                if welcome_msg.embeds:
                    e = welcome_msg.embeds[0]
                    new_embed = discord.Embed.from_dict(e.to_dict())
                    new_embed.add_field(
                        name="👤 Pris en charge par",
                        value=f"{member.mention}\n*depuis {discord.utils.format_dt(datetime.now(timezone.utc), 'R')}*",
                        inline=False,
                    )
                # Construit une nouvelle vue : claim désactivé + libellé mis à jour
                new_view = discord.ui.View(timeout=None)
                claim_btn = discord.ui.Button(
                    label=f"Pris en charge par {member.display_name}",
                    emoji="👤",
                    style=discord.ButtonStyle.success,
                    custom_id="miaouscle:ticket:claim",
                    disabled=True,
                )
                close_btn = discord.ui.Button(
                    label="Fermer le ticket",
                    emoji="🔒",
                    style=discord.ButtonStyle.danger,
                    custom_id="miaouscle:ticket:close",
                )

                async def _close_cb(i: discord.Interaction):
                    await TicketsCog.handle_close_ticket(i)
                close_btn.callback = _close_cb  # type: ignore[assignment]

                new_view.add_item(claim_btn)
                new_view.add_item(close_btn)

                await welcome_msg.edit(
                    embed=new_embed if new_embed else welcome_msg.embeds[0],
                    view=new_view,
                )
            except (discord.NotFound, discord.HTTPException) as e:
                logger.warning(f"Édition message d'accueil ticket échouée : {e}")

        await interaction.response.send_message(
            f"👤 {member.mention} prend en charge ce ticket.",
        )

    @staticmethod
    async def handle_close_ticket(interaction: discord.Interaction):
        guild = interaction.guild
        cfg = _get_guild_cfg(guild.id)
        ticket = cfg.get("tickets", {}).get(str(interaction.channel.id))
        if not ticket:
            await interaction.response.send_message("❌ Ce canal n'est pas un ticket actif.", ephemeral=True)
            return
        if not TicketsCog._can_close(interaction, cfg, ticket):
            await interaction.response.send_message(
                "❌ Seul le staff peut le fermer.", ephemeral=True,
            )
            return
        await interaction.response.send_message(
            "Confirme la fermeture de ce ticket :",
            view=CloseConfirmView(interaction.channel.id, interaction.user.id),
            ephemeral=True,
        )

    @staticmethod
    async def do_close_ticket(guild: discord.Guild, channel_id: int, closed_by: discord.Member):
        ch = guild.get_channel(channel_id)
        if ch is None:
            return

        # Idempotence : transition atomique open → closing. Si déjà closing/closed,
        # on sort sans rien faire (évite double envoi de message + double delete
        # quand deux confirmations arrivent en parallèle).
        already_closing = {"v": False}

        def _mark(c: dict):
            t = c.get("tickets", {}).get(str(channel_id))
            if not t:
                already_closing["v"] = True
                return
            if t.get("status") in ("closing", "closed"):
                already_closing["v"] = True
                return
            t["status"] = "closing"
            t["closed_at"] = datetime.now(timezone.utc).isoformat()
            t["closed_by"] = str(closed_by.id)
        await _update_guild_cfg(guild.id, _mark)

        if already_closing["v"]:
            return

        # Lire les données du ticket AVANT suppression du canal
        ticket_data = _get_guild_cfg(guild.id).get("tickets", {}).get(str(channel_id), {})

        try:
            await ch.send(
                embed=discord.Embed(
                    description=f"🔒 Ticket fermé par {closed_by.mention}. "
                                f"Suppression du canal dans 5 secondes…",
                    color=0xef4444,
                )
            )
            await asyncio.sleep(5)
            await ch.delete(reason=f"Ticket fermé par {closed_by}")
        except (discord.Forbidden, discord.HTTPException) as e:
            logger.warning(f"Impossible de supprimer le canal de ticket {channel_id} : {e}")
        finally:
            # Marque comme définitivement fermé (le canal peut avoir disparu)
            def _final(c: dict):
                t = c.get("tickets", {}).get(str(channel_id))
                if t:
                    t["status"] = "closed"
            try:
                await _update_guild_cfg(guild.id, _final)
            except Exception:
                pass

        # ── Embed récapitulatif envoyé après fermeture ──────────────────────
        try:
            recap_ch = guild.get_channel(_RECAP_CHANNEL_ID)
            if recap_ch is None:
                try:
                    recap_ch = await guild.fetch_channel(_RECAP_CHANNEL_ID)
                except Exception:
                    recap_ch = None

            if recap_ch is not None:
                # Infos du ticket
                ticket_num   = ticket_data.get("number", "?")
                creator_id   = ticket_data.get("creator_id")
                claimed_id   = ticket_data.get("claimed_by")
                opened_at_s  = ticket_data.get("opened_at")
                ticket_tier  = ticket_data.get("tier", TIER_FREE)

                # Résolution des membres
                creator_mention = f"<@{creator_id}>" if creator_id else "*(inconnu)*"
                claimed_mention = f"<@{claimed_id}>" if claimed_id else "*(personne)*"

                # Durée du ticket
                duration_str = "—"
                if opened_at_s:
                    try:
                        opened_dt = datetime.fromisoformat(opened_at_s)
                        if opened_dt.tzinfo is None:
                            opened_dt = opened_dt.replace(tzinfo=timezone.utc)
                        delta = datetime.now(timezone.utc) - opened_dt
                        total_s = int(delta.total_seconds())
                        h, rem  = divmod(total_s, 3600)
                        m, s    = divmod(rem, 60)
                        if h:
                            duration_str = f"{h}h {m}m {s}s"
                        elif m:
                            duration_str = f"{m}m {s}s"
                        else:
                            duration_str = f"{s}s"
                    except Exception:
                        pass

                # Statut Premium du serveur
                guild_tier = get_guild_tier(guild.id)
                _tier_labels = {
                    TIER_FREE:         "🆓 Gratuit",
                    TIER_PREMIUM:      "💎 Premium",
                    TIER_PREMIUM_PLUS: "👑 Premium+",
                }
                guild_tier_label  = _tier_labels.get(guild_tier,  guild_tier)
                ticket_tier_label = _tier_labels.get(ticket_tier, ticket_tier)

                # Couleur selon tier du ticket
                _tier_colors = {
                    TIER_FREE:         0x6b7280,
                    TIER_PREMIUM:      0xf59e0b,
                    TIER_PREMIUM_PLUS: 0xa855f7,
                }
                color = _tier_colors.get(ticket_tier, 0x6b7280)

                embed = discord.Embed(
                    title=f"📋 Ticket #{ticket_num:04d} — Récapitulatif",
                    color=color,
                    timestamp=datetime.now(timezone.utc),
                )
                embed.add_field(name="👤 Membre", value=creator_mention, inline=True)
                embed.add_field(name="🛠️ Pris en charge par", value=claimed_mention, inline=True)
                embed.add_field(name="🔒 Fermé par", value=closed_by.mention, inline=True)
                embed.add_field(name="⏱️ Durée", value=duration_str, inline=True)
                embed.add_field(name="🎫 Type de ticket", value=ticket_tier_label, inline=True)
                embed.add_field(name="💎 Premium serveur", value=guild_tier_label, inline=True)
                embed.set_footer(
                    text=f"Serveur : {guild.name}",
                    icon_url=guild.icon.url if guild.icon else None,
                )
                await recap_ch.send(embed=embed)
        except Exception as e:
            logger.warning(f"Impossible d'envoyer le récap du ticket {channel_id} : {e}")


async def setup(bot: commands.Bot):
    await bot.add_cog(TicketsCog(bot))

utils/auto_changelog.py:
"""
Auto Changelog System - Détecte les changements de commandes
"""
import os
import json
import hashlib
from typing import Dict, List, Tuple, Optional
import discord

HASHES_FILE = "file_hashes.json"
BACKUPS_FILE = "file_backups.json"
VERSION_FILE = "version.json"

def get_file_hash(filepath: str) -> str:
    """Calcule le hash SHA256 d'un fichier"""
    sha256_hash = hashlib.sha256()
    try:
        with open(filepath, "rb") as f:
            for byte_block in iter(lambda: f.read(4096), b""):
                sha256_hash.update(byte_block)
        return sha256_hash.hexdigest()
    except:
        return ""

def get_all_file_hashes() -> Dict[str, str]:
    """Récupère les hashes de tous les fichiers à tracker"""
    hashes = {}

    files_to_track = ["main.py"]
    dirs_to_track = ["cogs/", "utils/", "translations/"]

    for file in files_to_track:
        if os.path.exists(file):
            hashes[file] = get_file_hash(file)

    for directory in dirs_to_track:
        if os.path.isdir(directory):
            for root, dirs, files in os.walk(directory):
                dirs[:] = [d for d in dirs if not d.startswith('.')]
                for file in sorted(files):
                    if file.endswith('.py') or file.endswith('.json'):
                        filepath = os.path.join(root, file)
                        hashes[filepath] = get_file_hash(filepath)

    return hashes

def get_file_content(filepath: str) -> str:
    """Récupère le contenu complet d'un fichier"""
    try:
        with open(filepath, "r", encoding="utf-8", errors="ignore") as f:
            return f.read()
    except:
        return ""

def get_all_file_contents() -> Dict[str, str]:
    """Récupère le contenu de tous les fichiers à tracker"""
    contents = {}

    files_to_track = ["main.py"]
    dirs_to_track = ["cogs/", "utils/", "translations/"]

    for file in files_to_track:
        if os.path.exists(file):
            contents[file] = get_file_content(file)

    for directory in dirs_to_track:
        if os.path.isdir(directory):
            for root, dirs, files in os.walk(directory):
                dirs[:] = [d for d in dirs if not d.startswith('.')]
                for file in sorted(files):
                    if file.endswith('.py') or file.endswith('.json'):
                        filepath = os.path.join(root, file)
                        contents[filepath] = get_file_content(filepath)

    return contents

def load_last_hashes() -> Dict[str, str]:
    """Charge les hashes du dernier démarrage"""
    try:
        with open(HASHES_FILE, "r") as f:
            return json.load(f)
    except:
        return {}

def load_backups() -> Dict[str, str]:
    """Charge le contenu sauvegardé"""
    try:
        with open(BACKUPS_FILE, "r") as f:
            return json.load(f)
    except:
        return {}

def save_hashes(hashes: Dict[str, str]) -> None:
    """Sauvegarde les hashes actuels"""
    with open(HASHES_FILE, "w") as f:
        json.dump(hashes, f, indent=2)

def save_backups(contents: Dict[str, str]) -> None:
    """Sauvegarde le contenu actuel"""
    with open(BACKUPS_FILE, "w") as f:
        json.dump(contents, f, indent=2)

def get_current_version() -> str:
    """Récupère la version actuelle"""
    try:
        with open(VERSION_FILE, "r") as f:
            data = json.load(f)
            return data.get("version", "v11.43.0")
    except:
        return "v11.43.0"

def increment_version(current_version: str) -> str:
    """Incrémente la version"""
    try:
        parts = current_version.replace("v", "").split(".")
        if len(parts) >= 3:
            parts[-1] = str(int(parts[-1]) + 1)
            return "v" + ".".join(parts)
    except:
        pass
    return current_version

def save_version(version: str) -> None:
    """Sauvegarde la version"""
    with open(VERSION_FILE, "w") as f:
        json.dump({"version": version}, f, indent=2)

def extract_commands(content: str) -> set:
    """Extrait les noms des commandes slash du contenu"""
    commands = set()
    lines = content.split("\n")
    for i, line in enumerate(lines):
        if "@app_commands.command" in line:
            for next_line in lines[i:min(i+5, len(lines))]:
                if "async def " in next_line or "def " in next_line:
                    try:
                        func_name = next_line.split("def ")[1].split("(")[0].strip()
                        if func_name:
                            commands.add(func_name)
                    except:
                        pass
                    break
    return commands

def extract_functions_with_docs(content: str) -> dict:
    """Extrait toutes les fonctions avec leurs docstrings"""
    functions = {}
    lines = content.split("\n")

    for i, line in enumerate(lines):
        # Chercher les définitions de fonctions
        if line.strip().startswith("def ") or line.strip().startswith("async def "):
            try:
                func_name = line.split("def ")[1].split("(")[0].strip()

                # Chercher la docstring
                docstring = ""
                for j in range(i+1, min(i+10, len(lines))):
                    if '"""' in lines[j] or "'''" in lines[j]:
                        # Début d'une docstring
                        start_quote = '"""' if '"""' in lines[j] else "'''"
                        first_line = lines[j].split(start_quote)[1] if start_quote in lines[j] else ""

                        if first_line and start_quote in lines[j].split(start_quote)[2:]:
                            # Une ligne
                            docstring = first_line
                        else:
                            # Multi-lignes
                            for k in range(j+1, min(j+5, len(lines))):
                                if start_quote in lines[k]:
                                    docstring = lines[j] + " " + " ".join(lines[j+1:k])
                                    break
                        break

                if func_name and func_name != "_":
                    functions[func_name] = docstring.strip().replace('"""', '').replace("'''", '')
            except:
                pass

    return functions

def detect_command_changes(old_content: str, new_content: str) -> Tuple[List[str], List[str]]:
    """
    Détecte les changements de commandes
    Retourne (added, removed)
    """
    added = []
    removed = []

    if not old_content or not new_content:
        return added, removed

    old_commands = extract_commands(old_content)
    new_commands = extract_commands(new_content)

    # Commandes supprimées
    for cmd in sorted(old_commands - new_commands):
        removed.append(cmd)

    # Commandes nouvelles
    for cmd in sorted(new_commands - old_commands):
        added.append(cmd)

    return added, removed

def detect_improvements(old_content: str, new_content: str, filepath: str) -> List[str]:
    """
    Détecte les améliorations et changements de code
    Retourne une liste des améliorations détectées
    """
    improvements = []

    if not old_content or not new_content:
        return improvements

    old_funcs = extract_functions_with_docs(old_content)
    new_funcs = extract_functions_with_docs(new_content)

    # Détections intelligentes basées sur le nom du fichier et les changements
    if "moderation" in filepath.lower():
        if "generate_sanction_id" in new_funcs and "generate_sanction_id" not in old_funcs:
            improvements.append("✨ Nouveau système d'ID intelligent pour les sanctions")
        elif "generate_sanction_id" in new_funcs and "generate_sanction_id" in old_funcs:
            if len(new_funcs["generate_sanction_id"]) > len(old_funcs.get("generate_sanction_id", "")):
                improvements.append("⚙️ Amélioration du système d'ID pour les sanctions")

    if "levels" in filepath.lower():
        if "get_user_level" in new_funcs and new_funcs.get("get_user_level"):
            improvements.append("📊 Système de niveaux amélioré")

    if "general" in filepath.lower():
        if "ping" in new_funcs and "ping" in old_funcs:
            improvements.append("🏓 Amélioration de la commande /ping")

    # Détection générique des changements importants
    new_only = set(new_funcs.keys()) - set(old_funcs.keys())
    for func in new_only:
        if not func.startswith("_"):  # Ignorer les fonctions privées
            if "improvement" in new_funcs[func].lower():
                improvements.append(f"✨ Nouvelle fonction: {func}")

    return improvements

# REMOVED - recap system deleted

def create_log_embed(added_cmds: List[str], removed_cmds: List[str], version: str, improvements: Optional[List[str]] = None) -> discord.Embed:
    """Crée un embed LOG simplifié pour le salon logs (1440720849375068170)"""
    if improvements is None:
        improvements = []

    # Déterminer le type de changement principal et construire description
    all_items = []

    # Section AJOUTS
    if added_cmds:
        for cmd in added_cmds:
            all_items.append(f"✨ Nouvelle commande: /{cmd}")

    # Section SUPPRESSIONS
    if removed_cmds:
        for cmd in removed_cmds:
            all_items.append(f"⛔ Commande supprimée: /{cmd}")

    # Section MODIFICATIONS/AMÉLIORATIONS
    if improvements:
        for improvement in improvements:
            # Ajouter un bullet point si pas déjà présent
            if not improvement.startswith("•"):
                all_items.append(f"• {improvement}")
            else:
                all_items.append(improvement)

    # Déterminer titre et couleur selon le type de changement
    if improvements and not added_cmds and not removed_cmds:
        color = 0xffa500  # Orange - MODIFICATIONS
        title = "✨ Nouvelles Fonctionnalités:"
    elif added_cmds and not removed_cmds and not improvements:
        color = 0x00ff00  # Vert - AJOUTS
        title = "✨ Nouvelles Commandes:"
    elif removed_cmds and not added_cmds and not improvements:
        color = 0xff0000  # Rouge - SUPPRESSIONS
        title = "⛔ Commandes Supprimées:"
    else:
        color = 0x5865f2  # Bleu - MIXTE
        title = "🔄 Changements Détectés:"

    # Description avec tous les changements en bullet points
    description = "\n".join(all_items[:15])
    if len(all_items) > 15:
        description += f"\n... et **{len(all_items) - 15} autres** changements"

    embed = discord.Embed(
        title=title,
        description=description,
        color=color,
        timestamp=discord.utils.utcnow()
    )

    embed.set_footer(text=f"🐱 Miaouscle Bot • v{version}")
    return embed

def create_embed_added(commands: List[str], version: str) -> discord.Embed:
    """Crée un embed pour les commandes ajoutées"""
    embed = discord.Embed(
        title="✨ Nouvelles Commandes Ajoutées",
        color=0x00ff00,
        timestamp=discord.utils.utcnow()
    )
    embed.set_footer(text=f"Miaouscle Bot v{version}")

    description = "\n".join([f"• /{cmd}" for cmd in commands[:10]])
    embed.description = description

    if len(commands) > 10:
        embed.description += f"\n... et {len(commands) - 10} autres"

    return embed

def create_embed_removed(commands: List[str], version: str) -> discord.Embed:
    """Crée un embed pour les commandes supprimées"""
    embed = discord.Embed(
        title="⛔ Commandes Supprimées",
        color=0xff0000,
        timestamp=discord.utils.utcnow()
    )
    embed.set_footer(text=f"Miaouscle Bot v{version}")

    description = "\n".join([f"• /{cmd}" for cmd in commands[:10]])
    embed.description = description

    if len(commands) > 10:
        embed.description += f"\n... et {len(commands) - 10} autres"

    return embed

def create_embed_modified(added_cmds: List[str], removed_cmds: List[str], version: str) -> discord.Embed:
    """Crée un embed pour les modifications mixtes"""
    embed = discord.Embed(
        title="🔧 Modifications du Bot",
        color=0xffa500,
        timestamp=discord.utils.utcnow()
    )
    embed.set_footer(text=f"Miaouscle Bot v{version}")

    if added_cmds:
        added_text = "\n".join([f"✨ /{cmd}" for cmd in added_cmds[:5]])
        embed.add_field(name="Commandes Ajoutées", value=added_text, inline=False)
        if len(added_cmds) > 5:
            embed.add_field(name="", value=f"... et {len(added_cmds) - 5} autres", inline=False)

    if removed_cmds:
        removed_text = "\n".join([f"⛔ /{cmd}" for cmd in removed_cmds[:5]])
        embed.add_field(name="Commandes Supprimées", value=removed_text, inline=False)
        if len(removed_cmds) > 5:
            embed.add_field(name="", value=f"... et {len(removed_cmds) - 5} autres", inline=False)

    return embed

def check_and_update() -> Tuple[bool, Optional[discord.Embed], Optional[str]]:
    """
    Vérifie les changements de commandes et retourne (has_changes, embed_log, new_version)
    embed_log: Pour le salon logs unique (1440720849375068170)
    """
    current_hashes = get_all_file_hashes()
    current_contents = get_all_file_contents()
    last_hashes = load_last_hashes()
    backups = load_backups()
    current_version = get_current_version()

    # Premier démarrage
    if not last_hashes:
        print("📝 Première initialisation - sauvegarde des fichiers...")
        save_hashes(current_hashes)
        save_backups(current_contents)
        save_version(current_version)
        return False, None, None

    # Comparaison des changements RÉELS
    all_added = []
    all_removed = []
    changed_files = []

    for filepath, current_hash in current_hashes.items():
        last_hash = last_hashes.get(filepath, "")
        current_content = current_contents.get(filepath, "")
        old_content = backups.get(filepath, "")

        # Si le hash a changé
        if current_hash != last_hash and last_hash and old_content:
            changed_files.append(filepath)

            # Vérifier les changements de commandes
            added, removed = detect_command_changes(old_content, current_content)
            if added or removed:
                all_added.extend(added)
                all_removed.extend(removed)

    # Détecter aussi les améliorations et changements de code
    all_improvements: List[str] = []
    for filepath in changed_files:
        old_content = backups.get(filepath, "")
        current_content = current_contents.get(filepath, "")
        improvements = detect_improvements(old_content, current_content, filepath)
        if improvements:
            all_improvements.extend(improvements)

    # S'il y a des changements de commandes OU des améliorations
    if all_added or all_removed or all_improvements:
        # Incrémenter la version
        new_version = increment_version(current_version)
        save_version(new_version)

        # Sauvegarder les nouveaux fichiers
        save_hashes(current_hashes)
        save_backups(current_contents)

        # Créer SEULEMENT l'embed LOG avec détails clairs
        embed_log = create_log_embed(all_added, all_removed, new_version, all_improvements)

        print(f"✨ Nouvelles commandes: {', '.join(all_added) if all_added else 'aucune'}")
        print(f"⛔ Commandes supprimées: {', '.join(all_removed) if all_removed else 'aucune'}")
        print(f"💪 Améliorations détectées: {', '.join(all_improvements) if all_improvements else 'aucune'}")
        print(f"🔔 Changements détectés! Version: {current_version} → {new_version}")
        return True, embed_log, new_version
    else:
        # Pas de changements - juste sauvegarder pour la prochaine fois
        save_hashes(current_hashes)
        save_backups(current_contents)
        return False, None, None

